def transform(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0])
    objects = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(R) for c in range(C) if g[r][c] == color]
        if len(cells) < 9:
            continue
        for r, c in cells:
            if (r+2 < R and c+2 < C and
                all(g[i][j] == color for i in range(r, r+3) for j in range(c, c+3)) and
                (r == 0 or g[r-1][c] != color) and (c == 0 or g[r][c-1] != color)):
                objects.append((color, r+1, c+1))
    rays = {}
    for color, r, c in objects:
        for j in range(C):
            rays.setdefault((r, j), set()).add(color)
        for i in range(R):
            rays.setdefault((i, c), set()).add(color)
    for (r, c), colors in rays.items():
        if len(colors) == 1:
            g[r][c] = next(iter(colors))
        else:
            g[r][c] = 0
    return g
